def transform(grid):
    n = len(grid)
    m = len(grid[0])
    out = [[7] * m for _ in range(n)]
    colors = {cell for row in grid for cell in row if cell != 7}
    for color in colors:
        cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = color
    return out
